describe('revalidation-only responses', () => {
  /**
   * Serves a response with a validator but no freshness lifetime, answering
   * conditional requests with a 304.
   *
   * @param {Record<string, string>} headers headers sent with the full response
   */
  async function startValidatorOnlyServer (headers) {
    const state = { requestsToOrigin: 0, conditionalRequests: 0 }

    const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
      state.requestsToOrigin++

      if (req.headers['if-none-match'] === '"asd"') {
        state.conditionalRequests++
        res.statusCode = 304
        for (const [key, value] of Object.entries(headers)) {
          res.setHeader(key, value)
        }
        res.end()
        return
      }

      for (const [key, value] of Object.entries(headers)) {
        res.setHeader(key, value)
      }
      res.end('asd')
    }).listen(0)

    await once(server, 'listening')

    const client = new Client(`http://localhost:${server.address().port}`)
      .compose(interceptors.cache())

    after(async () => {
      server.close()
      await client.close()
    })

    return { state, client }
  }

  test('stores and revalidates a no-cache response with an etag', async () => {
    const { state, client } = await startValidatorOnlyServer({
      'cache-control': 'no-cache',
      etag: '"asd"'
    })

    const request = { origin: 'localhost', method: 'GET', path: '/' }

    // First request hits the origin unconditionally
    {
      const res = await client.request(request)
      equal(res.statusCode, 200)
      strictEqual(await res.body.text(), 'asd')
      equal(state.requestsToOrigin, 1)
      equal(state.conditionalRequests, 0)
    }

    // Second request revalidates the stored response and reuses its body
    {
      const res = await client.request(request)
      equal(res.statusCode, 200)
      strictEqual(await res.body.text(), 'asd')
      equal(state.requestsToOrigin, 2)
      equal(state.conditionalRequests, 1)
    }
  })

  test('stores and revalidates a max-age=0 response with an etag', async () => {
    const { state, client } = await startValidatorOnlyServer({
      'cache-control': 'max-age=0',
      etag: '"asd"'
    })

    const request = { origin: 'localhost', method: 'GET', path: '/' }

    {
      const res = await client.request(request)
      equal(res.statusCode, 200)
      strictEqual(await res.body.text(), 'asd')
      equal(state.requestsToOrigin, 1)
      equal(state.conditionalRequests, 0)
    }

    {
      const res = await client.request(request)
      equal(res.statusCode, 200)
      strictEqual(await res.body.text(), 'asd')
      equal(state.requestsToOrigin, 2)
      equal(state.conditionalRequests, 1)
    }
  })

  test('keeps storing a no-cache response that also has a last-modified header', async () => {
    const { state, client } = await startValidatorOnlyServer({
      'cache-control': 'no-cache',
      etag: '"asd"',
      'last-modified': new Date(Date.now() - 20000).toUTCString()
    })

    const request = { origin: 'localhost', method: 'GET', path: '/' }

    {
      const res = await client.request(request)
      equal(res.statusCode, 200)
      strictEqual(await res.body.text(), 'asd')
      equal(state.requestsToOrigin, 1)
      equal(state.conditionalRequests, 0)
    }

    // The heuristic freshness lifetime from last-modified must still win, so
    // this stays a conditional request rather than a second full one
    {
      const res = await client.request(request)
      equal(res.statusCode, 200)
      strictEqual(await res.body.text(), 'asd')
      equal(state.requestsToOrigin, 2)
      equal(state.conditionalRequests, 1)
    }
  })
})

