'use strict'

const { createServer } = require('node:http')
const { once } = require('node:events')
const { Client, interceptors, cacheStores: { MemoryCacheStore } } = require('./index')
const { makeCacheKey } = require('./lib/util/cache.js')

async function main () {
  let requests = 0
  let conditional = 0
  const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
    requests++
    res.setHeader('cache-control', 'no-cache')
    res.setHeader('etag', '"asd"')
    if (req.headers['if-none-match'] === '"asd"') {
      conditional++
      res.statusCode = 304
      res.end()
      return
    }
    res.end('asd')
  }).listen(0)
  await once(server, 'listening')

  const origin = `http://localhost:${server.address().port}`
  const store = new MemoryCacheStore()
  const client = new Client(origin).compose(interceptors.cache({ store }))

  for (let i = 1; i <= 3; i++) {
    const res = await client.request({ origin, method: 'GET', path: '/' })
    const body = await res.body.text()
    const entry = store.get(makeCacheKey({ origin, method: 'GET', path: '/', headers: {} }))
    console.log(`req ${i}: status=${res.statusCode} body=${JSON.stringify(body)} origin=${requests} conditional=${conditional} stored=${!!entry} retentionHours=${entry ? ((entry.deleteAt - Date.now()) / 3600000).toFixed(2) : '-'}`)
  }

  server.close()
  await client.close()
}

main()

